public void P3WriteGraph(string path)
{
    using (var writer = new System.IO.BinaryWriter(System.IO.File.Create(path)))
    {
        writer.Write("P3_FIXED_GRAPH_V1");
        writer.Write(ResolutionX); writer.Write(ResolutionZ); writer.Write(CellSize);
        writer.Write(Origin.x); writer.Write(Origin.y); writer.Write(maximumX); writer.Write(maximumZ);
        writer.Write(Clearance); writer.Write(CellCount);
        foreach (uint value in walkable) writer.Write(value);
        foreach (byte value in neighbours) writer.Write(value);
        foreach (double value in edgeCosts) writer.Write(value);
    }
}
