private static void P3AssertExact(Vector2[] expected, Vector2[] actual)
{
    if (expected.Length != actual.Length) throw new InvalidOperationException("P3 output length mismatch");
    for (int i = 0; i < expected.Length; i++)
        if (P3Bits(expected[i].x) != P3Bits(actual[i].x) || P3Bits(expected[i].y) != P3Bits(actual[i].y))
            throw new InvalidOperationException("P3 output bit mismatch at " + i);
}
public void P3RunFixedReplay(Vector2[] targets, float stopRadius, Vector2[] captured, string prefix)
{
    using (var writer = new System.IO.BinaryWriter(System.IO.File.Create(prefix + "-input.bin")))
    {
        writer.Write("P3_FIXED_INPUT_V1"); writer.Write(stopRadius); writer.Write(targets.Length);
        foreach (var p in targets) { writer.Write(p.x); writer.Write(p.y); }
    }
    using (var writer = new System.IO.BinaryWriter(System.IO.File.Create(prefix + "-expected.bin")))
    {
        writer.Write(captured.Length);
        foreach (var p in captured) { writer.Write(p.x); writer.Write(p.y); }
    }
    P3AssertExact(captured, CreateFlowField(targets, stopRadius));
    var stages = new double[4];
    for (int i = 0; i < 3; i++)
    {
        P3AssertExact(captured, CreateFlowField(targets, stopRadius));
        P3AssertExact(captured, P3TimedFlow(targets, stopRadius, stages));
    }
    var report = new P3ReplayReport { cells = CellCount, targets = targets.Length, stopRadius = stopRadius,
        capturedOutputMatches = true, allMeasuredOutputsMatch = true,
        stopwatchFrequency = System.Diagnostics.Stopwatch.Frequency, rows = new P3ReplayRow[12] };
    double toMs = 1000.0 / System.Diagnostics.Stopwatch.Frequency;
    for (int i = 0; i < report.rows.Length; i++)
    {
        var row = new P3ReplayRow { pair = i, timedFirst = (i % 2 != 0) };
        int g0 = GC.CollectionCount(0), g1 = GC.CollectionCount(1), g2 = GC.CollectionCount(2);
        Vector2[] baseline = null, timed = null;
        for (int pass = 0; pass < 2; pass++)
        {
            bool measureTimed = row.timedFirst ? pass == 0 : pass == 1;
            long allocationStart = GC.GetAllocatedBytesForCurrentThread();
            long started = System.Diagnostics.Stopwatch.GetTimestamp();
            Vector2[] result = measureTimed ? P3TimedFlow(targets, stopRadius, stages) : CreateFlowField(targets, stopRadius);
            double milliseconds = (System.Diagnostics.Stopwatch.GetTimestamp() - started) * toMs;
            long allocated = GC.GetAllocatedBytesForCurrentThread() - allocationStart;
            if (measureTimed) { timed = result; row.timedMs = milliseconds; row.timedAllocatedBytes = allocated; }
            else { baseline = result; row.baselineMs = milliseconds; row.baselineAllocatedBytes = allocated; }
        }
        row.gen0Collections = GC.CollectionCount(0) - g0;
        row.gen1Collections = GC.CollectionCount(1) - g1;
        row.gen2Collections = GC.CollectionCount(2) - g2;
        row.resetMs = stages[0]; row.seedMs = stages[1]; row.traversalMs = stages[2]; row.outputMs = stages[3];
        P3AssertExact(captured, baseline); P3AssertExact(captured, timed);
        report.rows[i] = row;
    }
    System.IO.File.WriteAllText(prefix + "-replay.json", JsonUtility.ToJson(report, true));
}

private Vector2[] P3TimedFlow(IReadOnlyList<Vector2> targets, float stopRadius, double[] stages)
{
    long t0 = System.Diagnostics.Stopwatch.GetTimestamp();
    ValidatePadding(stopRadius, nameof(stopRadius));
    var result = new Vector2[CellCount];
    heapCount = 0;
    for (int cell = 0; cell < CellCount; cell++)
    {
        distances[cell] = double.PositiveInfinity;
        nextCells[cell] = -1;
        heapPositions[cell] = -1;
    }
    long t1 = System.Diagnostics.Stopwatch.GetTimestamp();
    if (targets == null) return result;
    for (int i = 0; i < targets.Count; i++)
    {
        if (!TryGetCell(targets[i], out int target) || walkable[target] == 0 || distances[target] == 0) continue;
        distances[target] = 0;
        nextCells[target] = target;
        PushOrDecrease(target);
    }
    long t2 = System.Diagnostics.Stopwatch.GetTimestamp();
    while (heapCount > 0)
    {
        int cell = PopMinimum();
        for (int direction = 0; direction < 8; direction++)
        {
            if ((neighbours[cell] & (1 << direction)) == 0) continue;
            int adjacent = cell + StepZ[direction] * ResolutionX + StepX[direction];
            if (heapPositions[adjacent] == -2) continue;
            double cost = direction < 4 ? edgeCosts[cell * 4 + direction] :
                edgeCosts[adjacent * 4 + direction - 4];
            double candidate = distances[cell] + cost;
            if (candidate >= distances[adjacent]) continue;
            distances[adjacent] = candidate;
            nextCells[adjacent] = cell;
            PushOrDecrease(adjacent);
        }
    }
    long t3 = System.Diagnostics.Stopwatch.GetTimestamp();
    for (int cell = 0; cell < CellCount; cell++)
    {
        int next = nextCells[cell];
        if (next < 0 || next == cell || distances[cell] <= stopRadius) continue;
        Vector2 delta = CellCenter(next) - CellCenter(cell);
        double length = Math.Sqrt((double)delta.x * delta.x + (double)delta.y * delta.y);
        result[cell] = new Vector2((float)(delta.x / length), (float)(delta.y / length));
    }
    long t4 = System.Diagnostics.Stopwatch.GetTimestamp();
    double toMs = 1000.0 / System.Diagnostics.Stopwatch.Frequency;
    stages[0] = (t1 - t0) * toMs; stages[1] = (t2 - t1) * toMs;
    stages[2] = (t3 - t2) * toMs; stages[3] = (t4 - t3) * toMs;
    return result;
}

