private static readonly List<P3FixedSample> p3FixedSamples = new List<P3FixedSample>();
private static void P3CaptureFixed(TerrainNavigationGrid grid, IReadOnlyList<Vector2> goals, float radius, Vector2[] directions, int team)
{
    float seconds = Time.realtimeSinceStartup - runningSince;
    if (stage != 5 || seconds < 35 || seconds >= 47 || p3FixedSamples.Count >= 6) return;
    int window = (int)((seconds - 35) / 4);
    foreach (var sample in p3FixedSamples) if (sample.team == team && sample.window == window) return;
    var copy = new Vector2[goals.Count];
    for (int i = 0; i < copy.Length; i++) copy[i] = goals[i];
    p3FixedSamples.Add(new P3FixedSample { grid = grid, targets = copy, radius = radius,
        expected = (Vector2[])directions.Clone(), team = team, window = window, frame = Time.frameCount, seconds = seconds });
}
private static void P3ReplayCaptured()
{
    TerrainNavigationRuntime.P3DiagnosticCapture = null;
    if (p3FixedSamples.Count != 6) throw new InvalidOperationException("Expected six live P3 snapshots, got " + p3FixedSamples.Count);
    var graphs = new List<TerrainNavigationGrid>();
    var index = new P3SampleIndex { samples = new P3SampleIndexRow[p3FixedSamples.Count] };
    for (int i = 0; i < p3FixedSamples.Count; i++)
    {
        var sample = p3FixedSamples[i]; int graph = graphs.IndexOf(sample.grid);
        if (graph < 0)
        {
            graph = graphs.Count; graphs.Add(sample.grid);
            sample.grid.P3WriteGraph(Path.Combine(output, "fixed-graph-" + graph + ".bin"));
        }
        string prefix = "fixed-sample-" + i;
        index.samples[i] = new P3SampleIndexRow { prefix = prefix, graph = "fixed-graph-" + graph + ".bin",
            team = sample.team, window = sample.window, frame = sample.frame, seconds = sample.seconds,
            targetCount = sample.targets.Length, cells = sample.grid.CellCount, stopRadius = sample.radius };
        File.WriteAllText(Path.Combine(output, "fixed-input-index.json"), JsonUtility.ToJson(index, true));
        sample.grid.P3RunFixedReplay(sample.targets, sample.radius, sample.expected, Path.Combine(output, prefix));
    }
    File.WriteAllText(Path.Combine(output, "fixed-replay-complete.txt"), "6 snapshots; exact-bit comparison for captured/original/timed outputs; 12 measured alternating pairs plus 3 warmup pairs per snapshot. No candidate optimization applied.");
}

